// Konfigurasi.java
import java.util.HashMap;
import java.util.Map;

public class Konfigurasi {
    private static Konfigurasi instance;
    private Map<String, String> data = new HashMap<>();

    private Konfigurasi() {
    }

    public static Konfigurasi getInstance() {
        if (instance == null) {
            instance = new Konfigurasi();
        }
        return instance;
    }

    public void set(String kunci, String nilai) {
        data.put(kunci, nilai);
    }

    public String get(String kunci) {
        return data.get(kunci);
    }
}

