// Penerbit.java
import java.util.ArrayList;
import java.util.List;

public class Penerbit {
    private List<Pelanggan> daftar = new ArrayList<>();

    public void daftar(Pelanggan p) {
        if (!daftar.contains(p)) {
            daftar.add(p);
        }
    }

    public void batal(Pelanggan p) {
        daftar.remove(p);
    }

    public int jumlahPelanggan() {
        return daftar.size();
    }

    public void kirim(String pesan) {
        for (Pelanggan p : daftar) {
            p.terima(pesan);
        }
    }
}

